using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Threading.Tasks;
using Impostor.Api;
using Impostor.Api.Innersloth;
using Impostor.Api.Net.Inner;
using Impostor.Api.Net.Messages.Rpcs;
using Impostor.Api.Innersloth.GameOptions;
using Impostor.Server.LlmBots.Maps;
using Impostor.Server.Net.Inner.Objects;
using Impostor.Server.Net.State;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    internal sealed partial class BotAgent
    {
        private enum Mode
        {
            Idle,
            Walking,
            Working,
        }

        private readonly List<Vector2> _path = new();
        private readonly HashSet<uint> _fakeDone = new();
        private BotMap? _map;
        private Vector2 _pos;
        private bool _inGame;
        private Mode _mode;
        private int _pathIndex;
        private Func<ValueTask>? _onArrive;
        private Func<ValueTask>? _onWorkDone;
        private DateTime _workUntil;
        private DateTime _lastStepAt = DateTime.UtcNow;
        private DateTime _killReadyAt;
        private DateTime _frozenUntil;
        private DateTime _idleUntil;
        private DateTime _reportStartedAt;
        private DateTime? _selfReportAt;
        private byte? _selfReportVictim;
        private byte? _reportingBody;
        private int _emergenciesUsed;
        private TaskRun? _task;
        private string _activity = "idle";
        private bool _scanning;
        private byte _scannerCount;

        /// <summary>Gets or sets the hub that tells this agent what happens in the game.</summary>
        public GameEventHub? Hub { get; set; }

        /// <summary>Gets a short description of what the bot is doing, for status pages.</summary>
        public string Activity => _activity;

        public Vector2 Position => _pos;

        public bool InGame => _inGame;

        private float Speed(NormalGameOptions options) => 2.5f * options.PlayerSpeedMod * (float)_env.Config.TimeScale;

        private TimeSpan Scaled(double seconds) => TimeSpan.FromSeconds(seconds / Math.Max(0.01, _env.Config.TimeScale));

        partial void OnGameStarting()
        {
        }

        partial void OnGameEnded()
        {
            _inGame = false;
            _mode = Mode.Idle;
            _task = null;
            _meeting = null;
        }

        private async ValueTask TickGameplayAsync(Game game, DateTime now)
        {
            var me = Client.Me;
            var info = Client.MyInfo;
            if (me == null || info == null)
            {
                return;
            }

            if (game.GameState != GameStates.Started || info.RoleType == null)
            {
                if (_inGame && game.GameState != GameStates.Starting)
                {
                    _inGame = false;
                }

                return;
            }

            if (game.Options is not NormalGameOptions options)
            {
                return;
            }

            if (!_inGame)
            {
                await BeginGameAsync(game, me, info, options, now);
            }

            ProcessWorldEvents(game, info, now);

            if (_scanning && _mode != Mode.Working)
            {
                await EndVisualAsync();
            }

            var meeting = game.ActiveMeeting;
            if (meeting != null)
            {
                await MeetingTickAsync(game, me, info, options, meeting, now);
                return;
            }

            if (_meeting != null)
            {
                await EndMeetingAsync(game, info, options, now);
            }

            if (now < _frozenUntil)
            {
                return;
            }

            var dt = (float)Math.Min(0.5, (now - _lastStepAt).TotalSeconds);
            _lastStepAt = now;

            if (!info.IsDead)
            {
                UpdateVision(game, me, info, now);
            }

            if (info.IsDead && info.IsImpostor)
            {
                _activity = "haunting (dead impostor)";
                return;
            }

            if (!info.IsDead)
            {
                if (_selfReportAt != null && now >= _selfReportAt && _selfReportVictim is { } victim)
                {
                    _selfReportAt = null;
                    _selfReportVictim = null;
                    _log.LogInformation("Self-reporting the body of {Victim}", NameOf(game, victim));
                    await Client.ReportBodyAsync(victim);
                    Memory.HandledBodies.Add(victim);
                    return;
                }

                if (info.IsImpostor && await TryKillAsync(game, me, info, options, now))
                {
                    return;
                }

                if (info.IsImpostor)
                {
                    await MaybeSabotageAsync(game, info, options, now);
                }

                if (await TryReportBodyAsync(game, info, now))
                {
                    await AdvanceAsync(dt, now, options);
                    return;
                }

                if (!info.IsImpostor && await TrySabotageDutyAsync(game, now))
                {
                    await AdvanceAsync(dt, now, options);
                    return;
                }

                if (!info.IsImpostor && await TryEmergencyAsync(game, info, options, now))
                {
                    await AdvanceAsync(dt, now, options);
                    return;
                }
            }

            await AdvanceAsync(dt, now, options);

            if (_mode == Mode.Idle && now >= _idleUntil)
            {
                await ChooseNextActivityAsync(game, me, info, options, now);
            }
        }

        private async ValueTask BeginGameAsync(Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            _map = BotMap.Get(options.Map);
            while (_worldEvents.TryDequeue(out _))
            {
                // Chat from the lobby and other old news is not part of this game.
            }

            Memory.Reset(now);
            Route.Clear();
            _fakeDone.Clear();
            _task = null;
            _mode = Mode.Idle;
            _meeting = null;
            _emergenciesUsed = 0;
            _reportingBody = null;
            _selfReportAt = null;
            _lastStepAt = now;
            _idleUntil = now;

            var spawn = game.GameNet.ShipStatus?.GetSpawnLocation(me, game.PlayerCount, true) ?? _map.SpawnCenter;
            _pos = spawn;
            await Client.SnapToAsync(spawn);

            _killReadyAt = now + TimeSpan.FromSeconds(Math.Max(1, options.KillCooldown));
            _sabotageReadyAt = now + Scaled(45);
            _frozenUntil = now + Scaled(3);
            _inGame = true;

            _log.LogInformation(
                "Game begins: I am {Role} on {Map} at {Room}, {Tasks} tasks",
                info.RoleType,
                _map.Name,
                _map.RoomAt(spawn),
                info.Tasks.Count);
        }

        // ---------------------------------------------------------------- movement

        private void GoTo(Vector2 destination, string activity, Func<ValueTask>? onArrive = null)
        {
            if (_map == null)
            {
                return;
            }

            _path.Clear();
            _path.AddRange(_map.Nav.FindPath(_pos, destination));
            _pathIndex = 1;
            _mode = Mode.Walking;
            _onArrive = onArrive;
            _activity = activity;
        }

        private void StartWork(double seconds, string activity, Func<ValueTask>? onDone)
        {
            _mode = Mode.Working;
            _workUntil = DateTime.UtcNow + Scaled(seconds * (0.85 + (_rng.NextDouble() * 0.3)));
            _onWorkDone = onDone;
            _activity = activity;
        }

        private void StopMoving()
        {
            _mode = Mode.Idle;
            _onArrive = null;
            _onWorkDone = null;
        }

        private async ValueTask AdvanceAsync(float dt, DateTime now, NormalGameOptions options)
        {
            if (_mode == Mode.Walking)
            {
                var budget = Speed(options) * dt;
                var moved = false;
                while (budget > 0 && _pathIndex < _path.Count)
                {
                    var target = _path[_pathIndex];
                    var distance = Vector2.Distance(_pos, target);
                    if (distance <= budget)
                    {
                        _pos = target;
                        budget -= distance;
                        _pathIndex++;
                        moved = moved || distance > 0;
                    }
                    else
                    {
                        _pos += Vector2.Normalize(target - _pos) * budget;
                        budget = 0;
                        moved = true;
                    }
                }

                if (moved)
                {
                    await Client.SendPositionAsync(_pos);
                }

                if (_pathIndex >= _path.Count)
                {
                    _mode = Mode.Idle;
                    var callback = _onArrive;
                    _onArrive = null;
                    if (callback != null)
                    {
                        await callback();
                    }
                }
            }
            else if (_mode == Mode.Working && now >= _workUntil)
            {
                _mode = Mode.Idle;
                var callback = _onWorkDone;
                _onWorkDone = null;
                if (callback != null)
                {
                    await callback();
                }
            }
        }

        // ---------------------------------------------------------------- tasks and idling

        private async ValueTask ChooseNextActivityAsync(Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            if (_map == null)
            {
                return;
            }

            if (info.IsDead && !info.IsImpostor && !options.GhostsDoTasks)
            {
                _activity = "haunting (ghost, no ghost tasks)";
                _idleUntil = now + TimeSpan.FromSeconds(5);
                return;
            }

            if (info.IsImpostor && now >= _killReadyAt && TryStartHunting(game, info, now))
            {
                return;
            }

            var pending = info.Tasks.Where(t => (info.IsImpostor ? !_fakeDone.Contains(t.Id) : !t.Complete) && t.Task != null).ToList();
            if (pending.Count > 0)
            {
                var chosen = pending
                    .Select(t => (Task: t, Cost: TaskCost(t) * (0.7 + (_rng.NextDouble() * 0.6))))
                    .OrderBy(x => x.Cost)
                    .First().Task;
                StartTask(chosen, info);
                return;
            }

            // Nothing left to do: hang around somewhere.
            var rooms = _map.Rooms.ToList();
            var room = rooms[_rng.Next(rooms.Count)];
            var hub = _map.RoomHub(room);
            GoTo(hub, $"wandering to {BotMap.DisplayName(room)}", () =>
            {
                _idleUntil = DateTime.UtcNow + Scaled(3 + (_rng.NextDouble() * 6));
                _activity = $"standing in {BotMap.DisplayName(room)}";
                return default;
            });
        }

        private double TaskCost(TaskInfo task)
        {
            if (_map == null || task.Task == null || !_map.Tasks.TryGetValue(task.Task.Id, out var spec))
            {
                return 1000;
            }

            var first = spec.Consoles.Count > 0 ? spec.Consoles.Min(c => Vector2.Distance(_pos, c.Position)) : 20;
            return first;
        }

        private void StartTask(TaskInfo task, InnerPlayerInfo info)
        {
            if (_map == null || task.Task == null || !_map.Tasks.TryGetValue(task.Task.Id, out var spec))
            {
                _fakeDone.Add(task.Id);
                return;
            }

            var stops = TaskPlanner.Plan(_map, spec, _rng);
            _task = new TaskRun(task, stops);
            GoToNextStop(info);
        }

        private void GoToNextStop(InnerPlayerInfo info)
        {
            var run = _task;
            if (run == null || run.Index >= run.Stops.Count)
            {
                return;
            }

            var stop = run.Stops[run.Index];
            GoTo(stop.Position, $"walking to {BotMap.DisplayName(stop.Room)} for {stop.Label}", async () =>
            {
                await BeginVisualAsync(info, run);
                StartWork(stop.Seconds, $"doing {stop.Label} in {BotMap.DisplayName(stop.Room)}", async () =>
                {
                    await EndVisualAsync();
                    run.Index++;
                    if (run.Index >= run.Stops.Count)
                    {
                        await FinishTaskAsync(info, run);
                    }
                    else
                    {
                        GoToNextStop(info);
                    }
                });
            });
        }

        /// <summary>
        ///     Crewmates doing a visual task show the animation other players can see (the MedBay scan, the asteroids),
        ///     so watching humans can vouch for them. Impostors cannot, just like in the real game.
        /// </summary>
        /// <param name="info">Our player info.</param>
        /// <param name="run">The task being done.</param>
        /// <returns>A task that finishes when the animation was started.</returns>
        private async ValueTask BeginVisualAsync(InnerPlayerInfo info, TaskRun run)
        {
            var me = Client.Me;
            var type = run.Info.Task?.Type;
            if (me == null || type == null || info.IsImpostor || info.IsDead || Client.Game?.Options is not NormalGameOptions { VisualTasks: true })
            {
                return;
            }

            if (type == TaskTypes.SubmitScan)
            {
                _scanning = true;
                _scannerCount++;
                await Client.SendRpcAsync(me.NetId, RpcCalls.SetScanner, w => Rpc15SetScanner.Serialize(w, true, _scannerCount));
            }
            else if (type == TaskTypes.ClearAsteroids)
            {
                await Client.SendRpcAsync(me.NetId, RpcCalls.PlayAnimation, w => Rpc00PlayAnimation.Serialize(w, TaskTypes.ClearAsteroids));
            }
        }

        private async ValueTask EndVisualAsync()
        {
            var me = Client.Me;
            if (_scanning && me != null)
            {
                _scanning = false;
                await Client.SendRpcAsync(me.NetId, RpcCalls.SetScanner, w => Rpc15SetScanner.Serialize(w, false, _scannerCount));
            }
        }

        private async ValueTask FinishTaskAsync(InnerPlayerInfo info, TaskRun run)
        {
            _task = null;
            if (info.IsImpostor)
            {
                _fakeDone.Add(run.Info.Id);
                _idleUntil = DateTime.UtcNow + Scaled(1 + (_rng.NextDouble() * 3));
                return;
            }

            await Client.CompleteTaskAsync(run.Info.Id);
            _idleUntil = DateTime.UtcNow + Scaled(0.5 + (_rng.NextDouble() * 1.5));
            _log.LogDebug("Completed task {Task}", run.Stops[0].Label);
        }

        // ---------------------------------------------------------------- bodies and emergencies

        private async ValueTask<bool> TryReportBodyAsync(Game game, InnerPlayerInfo info, DateTime now)
        {
            foreach (var body in Memory.KnownBodies.Values.ToList())
            {
                if (Memory.HandledBodies.Contains(body.VictimId))
                {
                    continue;
                }

                if (info.IsImpostor && _rng.NextDouble() > 0.35)
                {
                    // Walk on as if nothing happened.
                    Memory.HandledBodies.Add(body.VictimId);
                    continue;
                }

                var distance = Vector2.Distance(_pos, body.Position);
                if (distance <= ReportRange)
                {
                    _log.LogInformation("Reporting the body of {Victim} in {Room}", NameOf(game, body.VictimId), _map?.RoomAt(body.Position));
                    Memory.HandledBodies.Add(body.VictimId);
                    _reportingBody = null;
                    StopMoving();
                    await Client.ReportBodyAsync(body.VictimId);
                    return true;
                }

                if (_reportingBody != body.VictimId)
                {
                    _reportingBody = body.VictimId;
                    _reportStartedAt = now;
                    GoTo(body.Position, $"running to report {NameOf(game, body.VictimId)}'s body");
                }
                else if ((now - _reportStartedAt).TotalSeconds > 40 / Math.Max(0.1, _env.Config.TimeScale))
                {
                    Memory.HandledBodies.Add(body.VictimId);
                    _reportingBody = null;
                }

                return true;
            }

            return false;
        }

        private async ValueTask<bool> TryEmergencyAsync(Game game, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            if (_emergenciesUsed >= options.NumEmergencyMeetings || _map == null)
            {
                return false;
            }

            var culprits = Memory.CaughtImpostors
                .Where(id => !Memory.KnownDead.Contains(id) && game.GameNet.GameData.GetPlayerById(id) is { IsDead: false })
                .ToList();
            if (culprits.Count == 0)
            {
                return false;
            }

            var culprit = culprits[0];
            var button = _map.EmergencyButton;
            if (Vector2.Distance(_pos, button) <= 2.2f)
            {
                _emergenciesUsed++;
                _log.LogInformation("Calling an emergency meeting about {Who}", NameOf(game, culprit));
                StopMoving();
                await Client.ReportBodyAsync(byte.MaxValue);
                return true;
            }

            if (_activity != "running to the emergency button")
            {
                GoTo(button, "running to the emergency button");
            }

            return true;
        }

        // ---------------------------------------------------------------- killing

        private static float KillRange(NormalGameOptions options)
        {
            return options.KillDistance switch
            {
                KillDistances.Short => 1.0f,
                KillDistances.Long => 2.3f,
                _ => 1.7f,
            };
        }

        private bool IsTeammate(InnerPlayerInfo me, byte id, Game game)
        {
            var other = game.GameNet.GameData.GetPlayerById(id);
            return me.IsImpostor && other != null && other.IsImpostor;
        }

        private bool TryStartHunting(Game game, InnerPlayerInfo info, DateTime now)
        {
            if (_map == null)
            {
                return false;
            }

            // Head for the last known position of a crewmate, or somewhere random.
            var prey = Memory.LastSeen.Values
                .Where(s => !Memory.KnownDead.Contains(s.PlayerId) && !IsTeammate(info, s.PlayerId, game) && game.GameNet.GameData.GetPlayerById(s.PlayerId) is { IsDead: false })
                .OrderByDescending(s => s.Time)
                .FirstOrDefault();

            Vector2 destination;
            string label;
            if (prey != null && (now - prey.Time).TotalSeconds < 40 && Vector2.Distance(prey.Position, _pos) > 4)
            {
                destination = prey.Position;
                label = $"hunting near {prey.Room}";
            }
            else
            {
                var rooms = _map.Rooms.ToList();
                var room = rooms[_rng.Next(rooms.Count)];
                destination = _map.RoomHub(room);
                label = $"looking for prey in {BotMap.DisplayName(room)}";
            }

            GoTo(destination, label, () =>
            {
                _idleUntil = DateTime.UtcNow + Scaled(1 + (_rng.NextDouble() * 3));
                return default;
            });
            return true;
        }

        private async ValueTask<bool> TryKillAsync(Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            if (now < _killReadyAt || _map == null)
            {
                return false;
            }

            var prey = _visible.Where(v => !IsTeammate(info, v.Id, game)).OrderBy(v => v.Distance).ToList();
            if (prey.Count == 0)
            {
                return false;
            }

            // Only strike when nobody else is looking.
            var target = prey[0];
            var witnesses = prey.Count - 1;
            if (witnesses > 0)
            {
                return false;
            }

            var range = KillRange(options);
            if (target.Distance > range)
            {
                GoTo(target.Position, $"stalking {target.Name}");
                return false;
            }

            var room = _map.RoomAt(target.Position);

            // One kill at a time per game, and only while both sides are still what we think they are.
            var killLock = Hub?.KillLock(game.Code);
            if (killLock != null)
            {
                await killLock.WaitAsync();
            }

            try
            {
                if (game.GameState != GameStates.Started || game.ActiveMeeting != null || info.IsDead || target.Control.PlayerInfo is not { IsDead: false, IsImpostor: false })
                {
                    return false;
                }

                _log.LogInformation("Killing {Victim} in {Room}", target.Name, room);
                StopMoving();
                await Client.CheckMurderAsync(target.Control);
            }
            finally
            {
                killLock?.Release();
            }

            _killReadyAt = now + TimeSpan.FromSeconds(Math.Max(1, options.KillCooldown));
            Memory.MyKills.Add((target.Id, room, now));
            Memory.HandledBodies.Add(target.Id);
            Memory.Note(now, $"I killed {target.Name} in {room}", target.Id, 10);

            // The killer ends up on top of the victim.
            _pos = target.Position;
            await Client.SendPositionAsync(_pos);

            if (_rng.NextDouble() < 0.2)
            {
                _selfReportAt = now + Scaled(1.2);
                _selfReportVictim = target.Id;
                Memory.HandledBodies.Remove(target.Id);
            }
            else
            {
                var far = _map.Rooms.OrderByDescending(r => Vector2.Distance(_map.RoomHub(r), _pos)).Take(4).OrderBy(_ => _rng.Next()).First();
                GoTo(_map.RoomHub(far), $"leaving the scene towards {BotMap.DisplayName(far)}");
            }

            return true;
        }

        private sealed class TaskRun
        {
            public TaskRun(TaskInfo info, List<TaskStop> stops)
            {
                Info = info;
                Stops = stops;
            }

            public TaskInfo Info { get; }

            public List<TaskStop> Stops { get; }

            public int Index { get; set; }
        }
    }
}

using System;
using System.Numerics;
using System.Threading.Tasks;
using Impostor.Api.Innersloth;
using Impostor.Server.Net.State;

namespace Impostor.Server.LlmBots
{
    /// <summary>
    ///     Waiting in the lobby: a bit of shuffling around the spot the host put the character on, so bots do not
    ///     stand frozen next to the humans.
    /// </summary>
    internal sealed partial class BotAgent
    {
        // Nothing checks walkability in the lobby, so stay close enough to the spawn spot not to clip the dropship walls.
        private const float LobbyRadius = 0.25f;

        private Vector2? _lobbyHome;
        private Vector2 _lobbyPos;
        private Vector2? _lobbyTarget;
        private DateTime _lobbyNextMove;
        private DateTime _lobbyLastStep = DateTime.UtcNow;

        private async ValueTask TickLobbyAsync(Game game, DateTime now)
        {
            var me = Client.Me;
            if (game.GameState != GameStates.NotStarted || me == null || ManagedByHost || !_env.Config.LobbyIdleMovement)
            {
                _lobbyHome = null;
                _lobbyTarget = null;
                return;
            }

            if (_lobbyHome == null)
            {
                _lobbyHome = me.NetworkTransform.Position;
                _lobbyPos = _lobbyHome.Value;
                _lobbyNextMove = now + TimeSpan.FromSeconds(2 + (_rng.NextDouble() * 6));
                _lobbyLastStep = now;
                return;
            }

            var dt = (float)Math.Min(0.5, (now - _lobbyLastStep).TotalSeconds);
            _lobbyLastStep = now;

            if (_lobbyTarget == null)
            {
                if (now >= _lobbyNextMove)
                {
                    var angle = _rng.NextDouble() * Math.PI * 2;
                    var radius = _rng.NextDouble() * LobbyRadius;
                    _lobbyTarget = _lobbyHome.Value + new Vector2((float)(Math.Cos(angle) * radius), (float)(Math.Sin(angle) * radius));
                }

                return;
            }

            var to = _lobbyTarget.Value - _lobbyPos;
            var step = 2.0f * dt;
            if (to.Length() <= step)
            {
                _lobbyPos = _lobbyTarget.Value;
                _lobbyTarget = null;
                _lobbyNextMove = now + TimeSpan.FromSeconds(3 + (_rng.NextDouble() * 9));
            }
            else
            {
                _lobbyPos += Vector2.Normalize(to) * step;
            }

            await Client.SendPositionAsync(_lobbyPos);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Threading;
using System.Threading.Tasks;
using Impostor.Api.Innersloth.GameOptions;
using Impostor.Server.LlmBots.Brain;
using Impostor.Server.LlmBots.Maps;
using Impostor.Server.Net.Inner.Objects;
using Impostor.Server.Net.State;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    internal sealed partial class BotAgent
    {
        private MeetingRun? _meeting;
        private DateTime? _meetingSeenAt;

        /// <summary>Gets a text log of what this bot said and decided, for transcripts.</summary>
        public Action<string>? Transcript { get; set; }

        private async ValueTask MeetingTickAsync(Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, InnerMeetingHud meeting, DateTime now)
        {
            if (_meeting == null || _meeting.NetId != meeting.NetId)
            {
                // The host may announce who reported before or after the meeting object shows up: give it a moment.
                _meetingSeenAt ??= now;
                if (_pendingMeetingEvent == null && (now - _meetingSeenAt.Value).TotalSeconds < 1.5)
                {
                    return;
                }

                _meetingSeenAt = null;
                await BeginMeetingAsync(game, me, info, options, meeting, now);
            }

            var run = _meeting!;
            if (info.IsDead)
            {
                return;
            }

            // Collect the answer of a brain that finished thinking.
            if (run.Pending is { IsCompleted: true } pending)
            {
                run.Pending = null;
                try
                {
                    var decision = await pending;
                    ApplyDecision(run, decision, now);
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    _log.LogWarning(ex, "Brain failed, using fallback");
                }
            }

            if (!run.OpeningStarted && now >= run.OpeningAt)
            {
                run.OpeningStarted = true;
                StartThinking(run, game, me, info, options, MeetingStage.Opening, now);
            }

            // Keep the conversation going: after the opening, answer new chat one short line at a time.
            if (run.OpeningStarted && run.Pending == null && run.Say.Count == 0 && !run.FinalStarted && now >= run.NextTurnAt && now >= run.ReplyAt
                && now < run.FinalThinkAt && run.Spoken < _env.Config.MaxLinesPerMeeting)
            {
                var relevance = ReplyRelevance(game, info, run);
                run.ChatConsidered = Memory.Chat.Count;
                if (relevance == 2 || (relevance == 1 && _rng.NextDouble() < 0.5))
                {
                    StartThinking(run, game, me, info, options, MeetingStage.Reply, now);
                    run.NextTurnAt = now + TimeSpan.FromSeconds((3 + (_rng.NextDouble() * 3)) * Math.Max(0.1, _env.Config.ChatPace));
                }
                else
                {
                    run.NextTurnAt = now + TimeSpan.FromSeconds(1.5 + _rng.NextDouble());
                }
            }

            if (!run.FinalStarted && now >= run.FinalThinkAt)
            {
                run.FinalStarted = true;

                // Keep the earlier choice when nothing new was said since we made it.
                if (run.Vote != null && Memory.Chat.Count <= run.ChatSeenAtDecision)
                {
                    run.FinalDone = true;
                }
                else
                {
                    StartThinking(run, game, me, info, options, MeetingStage.FinalVote, now);
                }
            }

            // Talk.
            if (run.Say.Count > 0 && !run.VoteCast && now >= run.NextSayAt && now < run.Deadline && run.Spoken < _env.Config.MaxLinesPerMeeting)
            {
                var line = run.Say.Dequeue();
                run.Spoken++;
                run.NextSayAt = now + TimeSpan.FromSeconds((2.5 + (_rng.NextDouble() * 3)) * Math.Max(0.1, _env.Config.ChatPace));
                Transcript?.Invoke($"[{info.PlayerName}] {line}");
                await Client.SendChatAsync(line);
            }

            // Vote.
            if (!run.VoteCast && now >= run.VoteAt)
            {
                var ready = run.FinalDone || now >= run.VoteAt + TimeSpan.FromSeconds(4) || now >= run.Deadline - TimeSpan.FromSeconds(1);
                if (ready && DateTime.UtcNow < run.Deadline + TimeSpan.FromSeconds(1))
                {
                    await CastVoteAsync(game, info, run, now);
                }
            }
        }

        private async ValueTask BeginMeetingAsync(Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, InnerMeetingHud meeting, DateTime now)
        {
            StopMoving();
            _task = null;
            _duty = null;
            Hub?.ReleaseConsoles(game.Code, this);
            _reportingBody = null;
            _selfReportAt = null;

            var number = Memory.MeetingsHeld;
            var start = now;
            var anim = _env.Config.MeetingAnimationSeconds;
            var discussion = Math.Max(0, options.DiscussionTime);
            var voting = Math.Max(5, options.VotingTime);

            var opening = start + TimeSpan.FromSeconds(anim + ((0.3 + (_rng.NextDouble() * 2)) * Math.Max(0.1, _env.Config.ChatPace)));
            var deadline = start + TimeSpan.FromSeconds(anim + discussion + voting - 3);
            var voteAt = start + TimeSpan.FromSeconds(anim + discussion + 0.5 + (_rng.NextDouble() * 5));
            if (voteAt > deadline)
            {
                voteAt = deadline;
            }

            var finalThink = voteAt - TimeSpan.FromSeconds(4);
            if (finalThink < opening + TimeSpan.FromSeconds(1))
            {
                finalThink = opening + TimeSpan.FromSeconds(1);
            }

            var reply = opening + TimeSpan.FromSeconds(4 * Math.Max(0.1, _env.Config.ChatPace));

            _meeting = new MeetingRun
            {
                NetId = meeting.NetId,
                Start = start,
                Number = number,
                OpeningAt = opening,
                ReplyAt = reply,
                FinalThinkAt = finalThink,
                VoteAt = voteAt,
                Deadline = deadline,
                Cts = new CancellationTokenSource(),
                Started = _pendingMeetingEvent,
            };
            _pendingMeetingEvent = null;

            // Whoever was seen close to the body a short while ago becomes a little suspicious.
            if (_meeting.Started is { BodyPosition: { } bodyPosition, BodyId: { } bodyId })
            {
                foreach (var seen in Memory.LastSeen.Values)
                {
                    var age = (now - seen.Time).TotalSeconds;
                    if (seen.PlayerId != bodyId && seen.PlayerId != info.PlayerId && age < 60 && Vector2.Distance(seen.Position, bodyPosition) < 9)
                    {
                        Memory.AddSuspicion(seen.PlayerId, 3.5 - (age / 30));
                        Memory.Note(now, $"{NameOf(game, seen.PlayerId)} was near where the body was found ({BotMemory.Ago(now, seen.Time)})", seen.PlayerId, 3);
                    }
                }
            }

            var spot = game.GameNet.ShipStatus?.GetSpawnLocation(me, game.PlayerCount, false) ?? _map?.MeetingCenter ?? _pos;
            _pos = spot;
            _activity = "in a meeting";
            if (!info.IsDead)
            {
                await Client.SnapToAsync(spot);
            }

            _log.LogInformation("Meeting #{Number} begins ({Reason})", number, DescribeMeetingReason(game, _meeting.Started));
            Transcript?.Invoke($"--- Meeting {number}: {DescribeMeetingReason(game, _meeting.Started)} ---");
        }

        private async ValueTask EndMeetingAsync(Game game, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            _meeting?.Cts.Cancel();
            _meeting = null;
            _meetingSeenAt = null;
            _task = null;
            StopMoving();
            _frozenUntil = now + Scaled(_env.Config.PostMeetingFreezeSeconds);
            _killReadyAt = now + TimeSpan.FromSeconds(Math.Max(1, options.KillCooldown));
            _idleUntil = _frozenUntil;
            _lastStepAt = now;
            Memory.KnownBodies.Clear();
            await ValueTask.CompletedTask;
        }

        private void StartThinking(MeetingRun run, Game game, InnerPlayerControl me, InnerPlayerInfo info, NormalGameOptions options, MeetingStage stage, DateTime now)
        {
            if (run.Pending != null)
            {
                if (stage != MeetingStage.FinalVote)
                {
                    return;
                }

                // The final vote matters more than an earlier line still being written.
                run.Cts.Cancel();
                run.Cts = new CancellationTokenSource();
            }

            var context = BuildContext(game, info, options, run, stage, now);
            var runCts = run.Cts;
            var limit = stage switch
            {
                MeetingStage.Opening => Math.Clamp((run.VoteAt - now).TotalSeconds - 4, 4, 15),
                MeetingStage.Reply => Math.Clamp((run.VoteAt - now).TotalSeconds - 3, 3, 10),
                _ => Math.Clamp((run.Deadline - now).TotalSeconds - 3, 3, 12),
            };
            var brain = Brain;
            run.Pending = Task.Run(async () =>
            {
                // A slow model must not leave the bot silent: after the limit the built-in heuristics answer instead.
                using var timeout = CancellationTokenSource.CreateLinkedTokenSource(runCts.Token);
                timeout.CancelAfter(TimeSpan.FromSeconds(limit));
                try
                {
                    return await brain.DecideAsync(context, timeout.Token);
                }
                catch (OperationCanceledException) when (!runCts.IsCancellationRequested)
                {
                    _log.LogWarning("{Brain} was too slow for the {Stage} step, using heuristics", brain.Name, stage);
                    return _fallback.Decide(context) with { Source = "heuristic (model too slow)" };
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    _log.LogWarning("{Brain} failed ({Message}), falling back to heuristics", brain.Name, ex.Message);
                    return _fallback.Decide(context);
                }
            });
            run.PendingStage = stage;
        }

        private void ApplyDecision(MeetingRun run, MeetingDecision decision, DateTime now)
        {
            var stage = run.PendingStage;
            if (decision.Vote != null)
            {
                run.Vote = decision.Vote;
            }

            foreach (var line in decision.Say)
            {
                var clean = CleanLine(line);
                if (clean.Length == 0 || run.SaidLines.Contains(clean))
                {
                    continue;
                }

                run.SaidLines.Add(clean);
                run.Say.Enqueue(clean);
            }

            if (stage == MeetingStage.Opening)
            {
                run.ChatSeenAtOpening = Memory.Chat.Count;
            }

            run.ChatSeenAtDecision = Memory.Chat.Count;

            if (stage == MeetingStage.FinalVote)
            {
                run.FinalDone = true;
            }

            if (run.NextSayAt < now)
            {
                run.NextSayAt = now + TimeSpan.FromMilliseconds(400 + _rng.Next(1500));
            }
        }

        private async ValueTask CastVoteAsync(Game game, InnerPlayerInfo info, MeetingRun run, DateTime now)
        {
            run.VoteCast = true;
            byte choice = 253;

            if (run.Vote == null && game.Options is NormalGameOptions voteOptions)
            {
                // The model never answered in time: decide with the built-in rules.
                run.Vote = _fallback.Decide(BuildContext(game, info, voteOptions, run, MeetingStage.FinalVote, now)).Vote;
            }

            var target = run.Vote;
            if (target != null && !string.Equals(target, "skip", StringComparison.OrdinalIgnoreCase))
            {
                var found = game.GameNet.GameData.Players.Values.FirstOrDefault(p => string.Equals(p.PlayerName, target, StringComparison.OrdinalIgnoreCase) && !p.IsDead && p.PlayerId != info.PlayerId);
                found ??= game.GameNet.GameData.Players.Values.FirstOrDefault(p => !p.IsDead && p.PlayerId != info.PlayerId && target.Contains(p.PlayerName, StringComparison.OrdinalIgnoreCase));
                if (found != null)
                {
                    choice = found.PlayerId;
                }
            }

            var label = choice == 253 ? "skip" : NameOf(game, choice);
            _log.LogInformation("Votes {Target}", label);
            Transcript?.Invoke($"[{info.PlayerName}] votes {label}");

            if (info.IsImpostor && choice != 253 && game.GameNet.GameData.GetPlayerById(choice) is { IsImpostor: true })
            {
                // Never vote out a teammate.
                choice = 253;
            }

            await Client.CastVoteAsync(choice);
        }

        private bool IsHumanPlayer(Game game, byte playerId)
        {
            var info = game.GameNet.GameData.GetPlayerById(playerId);
            var owner = info?.Controller?.OwnerId;
            if (owner == null)
            {
                return false;
            }

            return game.GetClientPlayer(owner.Value)?.Client is Impostor.Server.Net.Client { Connection: not BotConnection };
        }

        /// <summary>
        ///     Rates the chat lines that arrived since this bot last looked: 2 = answer them (they name this bot, or are from a
        ///     human nobody has answered yet), 1 = a chime-in is welcome, 0 = nothing new.
        /// </summary>
        private int ReplyRelevance(Game game, InnerPlayerInfo info, MeetingRun run)
        {
            var fresh = Memory.Chat.Skip(run.ChatConsidered).Where(l => l.SenderId != info.PlayerId).ToList();
            if (fresh.Count == 0)
            {
                return 0;
            }

            var name = info.PlayerName.ToLowerInvariant();
            var color = info.CurrentOutfit.Color.ToString().ToLowerInvariant();
            var best = 1;
            foreach (var line in fresh)
            {
                var text = line.Text.ToLowerInvariant();
                if (text.Contains(name) || text.Contains(color))
                {
                    return 2;
                }

                if (IsHumanPlayer(game, line.SenderId))
                {
                    // A human spoke: answer, unless another bot already did after them.
                    var index = Memory.Chat.IndexOf(line);
                    if (Memory.Chat.Skip(index + 1).All(l => IsHumanPlayer(game, l.SenderId) || l.SenderId == info.PlayerId))
                    {
                        return 2;
                    }
                }
            }

            return best;
        }

        private static string CleanLine(string text)
        {
            var t = text.Replace("\r", " ").Replace("\n", " ").Trim().Trim('"');
            if (t.Length > 100)
            {
                var cut = t.LastIndexOf(' ', 99);
                t = t.Substring(0, cut > 40 ? cut : 100);
            }

            return t;
        }

        private string DescribeMeetingReason(Game game, MeetingStartedWorldEvent? started)
        {
            if (started == null)
            {
                return "meeting called";
            }

            var reporter = started.ReporterId is { } r ? NameOf(game, r) : "someone";
            if (started.BodyId is { } b && b != byte.MaxValue)
            {
                var room = started.BodyPosition is { } p && _map != null ? _map.RoomAt(p) : "unknown";
                return $"{reporter} found {NameOf(game, b)}'s body in {room}";
            }

            return $"{reporter} called an emergency meeting";
        }

        private MeetingContext BuildContext(Game game, InnerPlayerInfo info, NormalGameOptions options, MeetingRun run, MeetingStage stage, DateTime now)
        {
            var confirmAlive = game.GameNet.GameData.Players.Values.ToList();
            var briefs = confirmAlive
                .Select(p => new PlayerBrief(
                    p.PlayerId,
                    p.PlayerName,
                    p.CurrentOutfit.Color.ToString(),
                    !p.IsDead && !p.Disconnected,
                    p.PlayerId == info.PlayerId,
                    info.IsImpostor && p.IsImpostor && p.PlayerId != info.PlayerId,
                    IsHumanPlayer(game, p.PlayerId)))
                .ToList();

            var me = briefs.First(b => b.IsMe);
            PlayerBrief? reporter = null;
            PlayerBrief? body = null;
            string? bodyRoom = null;
            var reason = "A meeting was called.";
            if (run.Started is { } started)
            {
                reporter = started.ReporterId is { } r ? briefs.FirstOrDefault(b => b.Id == r) : null;
                body = started.BodyId is { } bi && bi != byte.MaxValue ? briefs.FirstOrDefault(b => b.Id == bi) : null;
                bodyRoom = started.BodyPosition is { } bp && _map != null ? _map.RoomAt(bp) : null;
                reason = DescribeMeetingReason(game, started) + ".";
            }

            var observations = Memory.Notes
                .OrderBy(n => n.Time)
                .Select(n => $"{BotMemory.Ago(now, n.Time)}: {n.Text}")
                .TakeLast(14)
                .ToList();

            var sightings = Memory.Timeline
                .OrderBy(t => t.Time)
                .Select(t => $"{NameOf(game, t.PlayerId)} in {t.Room} ({BotMemory.Ago(now, t.Time)})")
                .TakeLast(14)
                .ToList();

            var secrets = new List<string>();
            if (info.IsImpostor)
            {
                var mates = briefs.Where(b => b.IsTeammate).Select(b => b.Name).ToList();
                secrets.Add(mates.Count == 0 ? "You are the only impostor." : "Your impostor teammates: " + string.Join(", ", mates) + ".");
                foreach (var kill in Memory.MyKills)
                {
                    secrets.Add($"You killed {NameOf(game, kill.Victim)} in {kill.Room} ({BotMemory.Ago(now, kill.Time)}).");
                }
            }

            var done = info.Tasks.Count(t => t.Complete);
            var tasks = new List<string>();
            if (!info.IsImpostor)
            {
                tasks.Add($"You completed {done} of {info.Tasks.Count} tasks.");
            }

            if (_map != null)
            {
                var doing = info.Tasks
                    .Where(t => t.Task != null && _map.Tasks.TryGetValue(t.Task.Id, out _))
                    .Select(t => (Spec: _map.Tasks[t.Task!.Id], t.Complete))
                    .Select(x => $"{TaskPlanner.Name(x.Spec.TaskType)} in {(x.Spec.Consoles.Count > 0 ? BotMap.DisplayName(x.Spec.Consoles[0].Room) : "various places")}{(x.Complete ? " (done)" : string.Empty)}")
                    .ToList();
                tasks.AddRange(doing);
            }

            return new MeetingContext
            {
                MapName = _map?.Name ?? "The Skeld",
                MeetingNumber = run.Number,
                Stage = stage,
                Me = me,
                IAmImpostor = info.IsImpostor,
                Players = briefs,
                Reason = reason,
                BodyRoom = bodyRoom,
                Reporter = reporter,
                Body = body,
                Observations = observations,
                Sightings = sightings,
                SecretFacts = secrets,
                MyTasks = tasks,
                MyRoute = Route.Where(r => r.Room != "-").Select(r => $"{r.Room} ({BotMemory.Ago(now, r.Since)})").TakeLast(6).ToList(),
                MyRouteRooms = Route.Select(r => r.Room).TakeLast(4).ToList(),
                History = Memory.History.ToList(),
                Chat = Memory.Chat.ToList(),
                Suspicion = new Dictionary<byte, double>(Memory.Suspicion),
                Caught = new HashSet<byte>(Memory.CaughtImpostors),
                SecondsLeft = Math.Max(0, (run.Deadline - now).TotalSeconds),
                MaxLines = Math.Max(1, stage switch { MeetingStage.Opening => Math.Min(2, _env.Config.MaxLinesPerMeeting - run.Spoken), MeetingStage.Reply => 1, _ => 1 }),
                Persona = Persona,
                PreferredModel = PreferredModel,
            };
        }

        private sealed class MeetingRun
        {
            public uint NetId { get; init; }

            public DateTime Start { get; init; }

            public int Number { get; init; }

            public DateTime OpeningAt { get; init; }

            public DateTime ReplyAt { get; init; }

            public DateTime FinalThinkAt { get; init; }

            public DateTime VoteAt { get; init; }

            public DateTime Deadline { get; init; }

            public CancellationTokenSource Cts { get; set; } = new();

            public MeetingStartedWorldEvent? Started { get; set; }

            public bool OpeningStarted { get; set; }

            public bool ReplyStarted { get; set; }

            public bool FinalStarted { get; set; }

            public bool FinalDone { get; set; }

            public bool VoteCast { get; set; }

            public int Spoken { get; set; }

            public int ChatSeenAtOpening { get; set; }

            public int ChatSeenAtDecision { get; set; }

            public int ChatConsidered { get; set; }

            public Task<MeetingDecision>? Pending { get; set; }

            public MeetingStage PendingStage { get; set; }

            public string? Vote { get; set; }

            public Queue<string> Say { get; } = new();

            public HashSet<string> SaidLines { get; } = new();

            public DateTime NextSayAt { get; set; }

            public DateTime NextTurnAt { get; set; }
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using Impostor.Api.Innersloth.GameOptions;
using Impostor.Server.LlmBots.Maps;
using Impostor.Server.Net.Inner.Objects;
using Impostor.Server.Net.State;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    internal sealed partial class BotAgent
    {
        private const float ReportRange = 4.0f;

        private readonly ConcurrentQueue<WorldEvent> _worldEvents = new();
        private readonly List<PlayerObservation> _visible = new();

        private MeetingStartedWorldEvent? _pendingMeetingEvent;

        public BotMemory Memory { get; } = new();

        internal List<(string Room, DateTime Since)> Route { get; } = new();

        internal IReadOnlyList<PlayerObservation> Visible => _visible;

        public void Observe(WorldEvent evt) => _worldEvents.Enqueue(evt);

        private static NormalGameOptions? OptionsOf(Game game) => game.Options as NormalGameOptions;

        private float VisionRadius(Game game, InnerPlayerInfo info)
        {
            var options = OptionsOf(game);
            var mod = options == null ? 1f : (info.IsImpostor ? options.ImpostorLightMod : options.CrewLightMod);
            return Math.Max(2.5f, 5.5f * Math.Max(0.5f, mod));
        }

        private bool CanSee(Vector2 from, Vector2 to, float radius)
        {
            var distance = Vector2.Distance(from, to);
            if (distance > radius)
            {
                return false;
            }

            if (distance <= 2.5f || _map == null)
            {
                return true;
            }

            // Walls are unknown, but a route that is much longer than the straight line means something is in between.
            return _map.Nav.PathLength(from, to) <= (1.9 * distance) + 1.5;
        }

        private string NameOf(Game game, byte playerId)
        {
            return game.GameNet.GameData.GetPlayerById(playerId)?.PlayerName ?? $"player {playerId}";
        }

        private void ProcessWorldEvents(Game game, InnerPlayerInfo me, DateTime now)
        {
            while (_worldEvents.TryDequeue(out var evt))
            {
                var myPos = evt.Snapshot.FirstOrDefault(p => p.Id == me.PlayerId).Position;
                var radius = VisionRadius(game, me);
                var amAlive = !me.IsDead;

                switch (evt)
                {
                    case MurderWorldEvent murder:
                    {
                        if (murder.KillerId == me.PlayerId || murder.VictimId == me.PlayerId || !amAlive)
                        {
                            break;
                        }

                        if (CanSee(myPos, murder.Position, radius))
                        {
                            var room = _map?.RoomAt(murder.Position) ?? "somewhere";
                            var killer = NameOf(game, murder.KillerId);
                            var victim = NameOf(game, murder.VictimId);
                            Memory.CaughtImpostors.Add(murder.KillerId);
                            Memory.KnownDead.Add(murder.VictimId);
                            Memory.AddSuspicion(murder.KillerId, 100);
                            Memory.Note(now, $"I SAW {killer} kill {victim} in {room}", murder.KillerId, 10);
                            _log.LogInformation("Witnessed {Killer} killing {Victim}", killer, victim);
                        }

                        break;
                    }

                    case VentWorldEvent vent:
                    {
                        if (vent.PlayerId == me.PlayerId || !amAlive)
                        {
                            break;
                        }

                        if (CanSee(myPos, vent.Position, radius))
                        {
                            var room = _map?.RoomAt(vent.Position) ?? "somewhere";
                            var who = NameOf(game, vent.PlayerId);
                            Memory.CaughtImpostors.Add(vent.PlayerId);
                            Memory.AddSuspicion(vent.PlayerId, 50);
                            Memory.Note(now, $"I SAW {who} {(vent.Entered ? "enter" : "exit")} a vent in {room}", vent.PlayerId, 9);
                        }

                        break;
                    }

                    case MeetingStartedWorldEvent started:
                        Memory.MeetingsHeld++;
                        Memory.KnownBodies.Clear();
                        Memory.Chat.Clear();
                        if (_meeting != null && _meeting.Started == null)
                        {
                            _meeting.Started = started;
                        }
                        else
                        {
                            _pendingMeetingEvent = started;
                        }

                        break;

                    case ChatWorldEvent chat:
                        Memory.Chat.Add(new ChatLine(chat.Time, chat.SenderId, NameOf(game, chat.SenderId), chat.Text));
                        if (Memory.Chat.Count > 60)
                        {
                            Memory.Chat.RemoveAt(0);
                        }

                        break;

                    case MeetingEndedWorldEvent ended:
                        OnMeetingResult(game, me, ended, now);
                        break;

                    case GameEndedWorldEvent:
                        Memory.Reset(now);
                        break;
                }
            }
        }

        private void OnMeetingResult(Game game, InnerPlayerInfo me, MeetingEndedWorldEvent ended, DateTime now)
        {
            var votes = string.Join(", ", ended.Votes.Select(v => $"{NameOf(game, v.Voter)}->{(v.Target == 253 ? "skip" : NameOf(game, v.Target))}"));
            string result;
            if (ended.ExiledId is { } id)
            {
                var info = game.GameNet.GameData.GetPlayerById(id);
                var confirm = OptionsOf(game)?.ConfirmImpostor ?? true;
                var role = confirm && info != null ? (info.IsImpostor ? "was an impostor" : "was NOT an impostor") : "role unknown";
                result = $"{NameOf(game, id)} was voted out ({role})";
                Memory.KnownDead.Add(id);
                if (confirm && info != null)
                {
                    Memory.ExiledWasImpostor[id] = info.IsImpostor;
                }
            }
            else
            {
                result = ended.Tie ? "the vote was tied, nobody ejected" : "nobody was ejected";
            }

            Memory.History.Add($"Meeting {Memory.MeetingsHeld}: {result}. Votes: {(votes.Length == 0 ? "none" : votes)}");
        }

        private void UpdateVision(Game game, InnerPlayerControl me, InnerPlayerInfo info, DateTime now)
        {
            _visible.Clear();
            if (_map == null)
            {
                return;
            }

            var radius = VisionRadius(game, info);
            var room = _map.RoomAt(_pos);
            if (Route.Count == 0 || Route[^1].Room != room)
            {
                Route.Add((room, now));
                if (Route.Count > 12)
                {
                    Route.RemoveAt(0);
                }
            }

            foreach (var player in game.Players)
            {
                if (player.Character is not InnerPlayerControl other || other == me || other.PlayerInfo is not { } otherInfo)
                {
                    continue;
                }

                if (otherInfo.IsDead || otherInfo.Disconnected)
                {
                    continue;
                }

                var position = other.NetworkTransform.Position;
                if (!CanSee(_pos, position, radius))
                {
                    continue;
                }

                var otherRoom = _map.RoomAt(position);
                _visible.Add(new PlayerObservation(otherInfo.PlayerId, otherInfo.PlayerName, position, otherRoom, Vector2.Distance(_pos, position), other));
                Memory.RecordSighting(new Sighting(otherInfo.PlayerId, otherRoom, position, now));
            }

            foreach (var body in Hub?.BodiesOf(game.Code) ?? Array.Empty<BodyRecord>())
            {
                if (Memory.KnownBodies.ContainsKey(body.VictimId) || body.VictimId == me.PlayerId)
                {
                    continue;
                }

                if (CanSee(_pos, body.Position, radius))
                {
                    Memory.KnownBodies[body.VictimId] = body;
                    Memory.KnownDead.Add(body.VictimId);
                    Memory.Note(now, $"I found the body of {NameOf(game, body.VictimId)} in {_map.RoomAt(body.Position)}", body.VictimId, 6);
                }
            }

            _ = room;
        }
    }

    internal readonly record struct PlayerObservation(byte Id, string Name, Vector2 Position, string Room, float Distance, InnerPlayerControl Control);
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Threading.Tasks;
using Impostor.Api.Innersloth;
using Impostor.Api.Innersloth.GameOptions;
using Impostor.Server.Net.Inner.Objects;
using Impostor.Server.Net.Inner.Objects.Systems.ShipStatus;
using Impostor.Server.Net.State;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    /// <summary>
    ///     Crewmate bots run to fix the two sabotages that end the game: reactor meltdown and O2.
    ///     Two bots each take one of the two consoles; the game host decides when the system counts as repaired.
    /// </summary>
    internal sealed partial class BotAgent
    {
        private RepairDuty? _duty;
        private DateTime _sabotageReadyAt = DateTime.MaxValue;

        internal bool CanRepair(Game game)
        {
            var info = Client.MyInfo;
            return _inGame && !Finished && info is { IsDead: false, IsImpostor: false } && _meeting == null && game.ActiveMeeting == null;
        }

        /// <summary>
        ///     An impostor bot occasionally starts a reactor meltdown or an O2 failure, which the crew (bots included) must fix.
        /// </summary>
        /// <param name="game">The game.</param>
        /// <param name="info">Our player info.</param>
        /// <param name="options">Game options.</param>
        /// <param name="now">The time.</param>
        /// <returns>A task that finishes when the decision was made (and the sabotage sent).</returns>
        private async ValueTask MaybeSabotageAsync(Game game, InnerPlayerInfo info, NormalGameOptions options, DateTime now)
        {
            if (!info.IsImpostor || info.IsDead || now < _sabotageReadyAt || _env.Config.ImpostorSabotageChance <= 0)
            {
                return;
            }

            _sabotageReadyAt = now + TimeSpan.FromSeconds(90 + (_rng.NextDouble() * 60));
            if (options.Map is not (MapTypes.Skeld or MapTypes.Dleks or MapTypes.MiraHQ) || FindSabotage(game) != null || game.ActiveMeeting != null)
            {
                return;
            }

            var crew = game.GameNet.GameData.Players.Values.Count(p => !p.IsImpostor && !p.IsDead && !p.Disconnected);
            if (crew < 3 || _rng.NextDouble() > _env.Config.ImpostorSabotageChance)
            {
                return;
            }

            var target = _rng.Next(2) == 0 ? SystemTypes.Reactor : SystemTypes.LifeSupp;
            _log.LogInformation("Sabotaging: {Target}", target);
            await Client.SendUpdateSystemAsync(SystemTypes.Sabotage, (byte)target);
        }

        private static ActiveSabotage? FindSabotage(Game game)
        {
            var ship = game.GameNet.ShipStatus;
            if (ship == null)
            {
                return null;
            }

            foreach (var (type, system) in ship.Systems)
            {
                if (system is ReactorSystemType { IsActive: true } reactor)
                {
                    return new ActiveSabotage(type, false, reactor.Countdown);
                }

                if (system is LifeSuppSystemType { IsActive: true } o2)
                {
                    return new ActiveSabotage(type, true, o2.Countdown);
                }
            }

            return null;
        }

        private async ValueTask<bool> TrySabotageDutyAsync(Game game, DateTime now)
        {
            var active = FindSabotage(game);
            if (active == null)
            {
                if (_duty != null)
                {
                    await FinishDutyAsync(game, now, "the sabotage is fixed");
                }

                return false;
            }

            var sabotage = active.Value;
            if (_map == null)
            {
                return false;
            }

            if (_duty != null && _duty.System != sabotage.System)
            {
                await FinishDutyAsync(game, now, "a different sabotage started");
            }

            if (_duty == null)
            {
                _duty = ChooseDuty(game, sabotage, now);
                if (_duty == null)
                {
                    return false;
                }

                _log.LogInformation("Rushing to fix the {What} (console {Console})", sabotage.IsO2 ? "O2" : "reactor", _duty.Console);
                GoTo(_duty.Position, $"rushing to fix the {(sabotage.IsO2 ? "O2" : "reactor")}");
            }

            var duty = _duty;
            if ((now - duty.Since).TotalSeconds > 75)
            {
                await FinishDutyAsync(game, now, "gave up");
                return false;
            }

            if (_mode == Mode.Walking)
            {
                return true;
            }

            if (!duty.Arrived)
            {
                if (Vector2.Distance(_pos, duty.Position) > 1.5f)
                {
                    GoTo(duty.Position, $"rushing to fix the {(sabotage.IsO2 ? "O2" : "reactor")}");
                    return true;
                }

                duty.Arrived = true;
                duty.ArrivedAt = now;
                _activity = sabotage.IsO2 ? "entering the O2 code" : "holding a reactor console";
                if (!sabotage.IsO2)
                {
                    await Client.SendUpdateSystemAsync(duty.System, (byte)(0x40 | duty.Console));
                }
            }

            if (sabotage.IsO2 && !duty.Confirmed && (now - duty.ArrivedAt).TotalSeconds >= 4 / Math.Max(0.1, _env.Config.TimeScale))
            {
                duty.Confirmed = true;
                await Client.SendUpdateSystemAsync(duty.System, (byte)(0x40 | duty.Console));
            }

            return true;
        }

        private async ValueTask FinishDutyAsync(Game game, DateTime now, string why)
        {
            var duty = _duty;
            _duty = null;
            Hub?.ReleaseConsoles(game.Code, this);
            if (duty == null)
            {
                return;
            }

            _log.LogInformation("Repair duty over: {Why}", why);
            if (duty.Arrived && !duty.IsO2)
            {
                await Client.SendUpdateSystemAsync(duty.System, (byte)(0x20 | duty.Console));
            }

            StopMoving();
            _idleUntil = now;
        }

        private RepairDuty? ChooseDuty(Game game, ActiveSabotage sabotage, DateTime now)
        {
            if (_map == null || Hub == null)
            {
                return null;
            }

            var candidates = Hub.AgentsOf(game.Code).Where(a => a.CanRepair(game)).ToList();
            if (!candidates.Contains(this))
            {
                return null;
            }

            foreach (var (id, position) in SabotageConsoles(sabotage))
            {
                var ranked = candidates
                    .OrderBy(a => _map.Nav.PathLength(a.Position, position))
                    .Take(2)
                    .ToList();
                if (ranked.Contains(this) && Hub.TryClaimConsole(game.Code, (int)sabotage.System, id, this))
                {
                    return new RepairDuty(sabotage.System, sabotage.IsO2, id, position, now);
                }
            }

            return null;
        }

        private IReadOnlyList<(int Id, Vector2 Position)> SabotageConsoles(ActiveSabotage sabotage)
        {
            var map = _map!;
            if (map.HasHandmadeGraph)
            {
                return sabotage.IsO2
                    ? new[] { (0, map.Nav["O2_C"].Position), (1, map.Nav["ADM_C"].Position) }
                    : new[] { (0, map.Nav["RX_MANI"].Position), (1, map.Nav["RX_START"].Position) };
            }

            var room = sabotage.System == SystemTypes.Laboratory ? "Laboratory" : (sabotage.IsO2 ? "LifeSupp" : "Reactor");
            var hub = map.RoomHub(room);
            return new[] { (0, hub + new Vector2(-1.2f, 0)), (1, hub + new Vector2(1.2f, 0)) };
        }

        internal readonly record struct ActiveSabotage(SystemTypes System, bool IsO2, float Countdown);

        private sealed class RepairDuty
        {
            public RepairDuty(SystemTypes system, bool isO2, int console, Vector2 position, DateTime since)
            {
                System = system;
                IsO2 = isO2;
                Console = console;
                Position = position;
                Since = since;
            }

            public SystemTypes System { get; }

            public bool IsO2 { get; }

            public int Console { get; }

            public Vector2 Position { get; }

            public DateTime Since { get; }

            public bool Arrived { get; set; }

            public DateTime ArrivedAt { get; set; }

            public bool Confirmed { get; set; }
        }
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;
using Impostor.Api.Innersloth;
using Impostor.Api.Innersloth.Customization;
using Impostor.Server.LlmBots.Brain;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    /// <summary>
    ///     Drives one bot: reacts to protocol events and, every tick, decides what the bot does next.
    /// </summary>
    internal sealed partial class BotAgent
    {
        private readonly BotEnvironment _env;
        private readonly ILogger _log;
        private static readonly string[] Personas =
        {
            "terse and to the point, few words",
            "friendly and chatty, likes to ask questions",
            "suspicious by nature, quick to point fingers but wants evidence",
            "calm and analytical, thinks out loud about who was where",
            "joker who keeps things light but still plays to win",
            "nervous and a bit scatterbrained, second-guesses themselves",
            "confident and bossy, tells everybody who to vote for",
            "quiet, only speaks when they have something concrete",
        };

        private static readonly string[] Greetings = { "hi!", "hey all", "yo", "ready when you are", "hello", "gl hf", "lets go", "sup" };

        private readonly Random _rng;
        private readonly HeuristicBrain _fallback;
        private bool _identitySent;
        private DateTime? _readyAt;
        private DateTime? _rejoinAt;
        private bool _waitingForHost;
        private uint? _staleControlId;
        private DateTime? _greetAt;
        private bool _sceneWanted;

        public BotAgent(BotEnvironment env, BotClient client, int seed)
        {
            _env = env;
            Client = client;
            _rng = new Random(seed);
            Hub = env.Hub;
            Persona = Personas[Math.Abs(seed) % Personas.Length];
            Brain = new HeuristicBrain(seed);
            _fallback = new HeuristicBrain(seed + 7);
            _log = env.LoggerFactory.CreateLogger($"Agent[{client.Name}]");
        }

        public BotClient Client { get; }

        public IBrain Brain { get; set; }

        /// <summary>
        ///     Gets or sets a value indicating whether the scene change handshake is done by someone else (the scripted host).
        /// </summary>
        public bool ManagedByHost { get; set; }

        public string Persona { get; }

        /// <summary>Gets or sets the language model this bot is named after; it is asked first in meetings.</summary>
        public string? PreferredModel { get; set; }

        public bool Finished { get; private set; }

        public string? FinishReason { get; private set; }

        public async Task RunAsync(CancellationToken ct)
        {
            while (!ct.IsCancellationRequested && !Finished)
            {
                try
                {
                    foreach (var evt in Client.DrainInbox())
                    {
                        await HandleEventAsync(evt);
                    }

                    await TickAsync();
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    _log.LogError(ex, "Agent loop error");
                }

                try
                {
                    await Task.Delay(TickMilliseconds, ct);
                }
                catch (OperationCanceledException)
                {
                    break;
                }
            }
        }

        public async ValueTask HandleEventAsync(BotEvent evt)
        {
            switch (evt.Kind)
            {
                case BotEventKind.Joined:
                    if (Client.Code != null)
                    {
                        Hub?.Register(Client.Code.Value, this);
                    }

                    _identitySent = false;
                    _rejoinAt = null;
                    _sceneWanted = !ManagedByHost;
                    break;

                case BotEventKind.GameStarted:
                    _readyAt = DateTime.UtcNow + TimeSpan.FromMilliseconds(_rng.Next(200, 900));
                    OnGameStarting();
                    break;

                case BotEventKind.GameEnded:
                    _rejoinAt = DateTime.UtcNow + TimeSpan.FromSeconds(_env.Config.EndScreenSeconds + _rng.NextDouble());
                    OnGameEnded();
                    break;

                case BotEventKind.Removed when evt.A == Client.ClientId:
                case BotEventKind.Kicked when evt.A == Client.ClientId:
                case BotEventKind.Disconnected:
                    Finish(evt.Kind.ToString() + (evt.Text != null ? ": " + evt.Text : string.Empty));
                    break;
            }
        }

        public async ValueTask TickAsync()
        {
            var game = Client.Game;
            if (game == null || Finished)
            {
                return;
            }

            var now = DateTime.UtcNow;

            if (_sceneWanted)
            {
                _sceneWanted = false;
                await Client.SendSceneChangeAsync();
            }

            if (!_identitySent && Client.Me != null && Client.Me.NetId != _staleControlId)
            {
                _identitySent = true;
                var color = Client.Client?.PreviousColor is { } previous && (int)previous >= 0 ? previous : (ColorType)_rng.Next(0, Enum.GetValues<ColorType>().Length);
                await Client.SetupIdentityAsync(color, (uint)_rng.Next(3, 60));

                if (!ManagedByHost && _rng.NextDouble() < 0.45)
                {
                    _greetAt = now + TimeSpan.FromSeconds(1.5 + (_rng.NextDouble() * 5));
                }
            }

            if (_greetAt != null && now >= _greetAt)
            {
                _greetAt = null;
                if (game.GameState == Impostor.Api.Innersloth.GameStates.NotStarted)
                {
                    await Client.SendChatAsync(Greetings[_rng.Next(Greetings.Length)]);
                }
            }

            if (_readyAt != null && now >= _readyAt)
            {
                _readyAt = null;
                await Client.SendReadyAsync();
            }

            if (_rejoinAt != null && now >= _rejoinAt && Client.Code != null)
            {
                // Like real players, wait on the game over screen until the human host has gone back to the lobby:
                // bots that rejoin first make the server announce them to a client that is still on the end screen.
                var humanHost = game.Host?.Client is Impostor.Server.Net.Client { Connection: not BotConnection };
                if (game.GameState == Impostor.Api.Innersloth.GameStates.Ended && humanHost)
                {
                    _waitingForHost = true;
                }
                else
                {
                    if (_waitingForHost)
                    {
                        // The host is back: come in a moment later, not all in the same instant.
                        _waitingForHost = false;
                        _rejoinAt = now + TimeSpan.FromSeconds(1 + (_rng.NextDouble() * 2.5));
                    }
                    else
                    {
                        _rejoinAt = null;
                        _staleControlId = await Client.DespawnMineAsync() ?? Client.Me?.NetId;
                        await Client.JoinAsync(Client.Code.Value);
                    }
                }
            }

            await TickLobbyAsync(game, now);
            await TickGameplayAsync(game, now);
        }

        public void Finish(string reason)
        {
            if (!Finished)
            {
                Finished = true;
                FinishReason = reason;

                _log.LogInformation("Finished: {Reason}", reason);
            }
        }

        private static int TickMilliseconds => 100;

        partial void OnGameStarting();

        partial void OnGameEnded();
    }
}

using System;
using System.Collections.Generic;
using System.Numerics;
using System.Threading.Tasks;
using Impostor.Api;
using Impostor.Api.Games;
using Impostor.Api.Innersloth;
using Impostor.Api.Innersloth.Customization;
using Impostor.Api.Net;
using Impostor.Api.Net.Inner;
using Impostor.Api.Net.Messages;
using Impostor.Api.Net.Messages.Rpcs;
using Impostor.Hazel;
using Impostor.Hazel.Abstractions;
using Impostor.Server.Net;
using Impostor.Server.Net.Inner;
using Impostor.Server.Net.Inner.Objects;
using Impostor.Server.Net.State;
using Microsoft.Extensions.Logging;

namespace Impostor.Server.LlmBots
{
    internal enum BotEventKind
    {
        Joined,
        WaitForHost,
        GameStarted,
        GameEnded,
        Removed,
        Kicked,
        Disconnected,
        HostedGame,
        SceneChanged,
        ClientReady,
        Rpc,
        Spawned,
        Despawned,
    }

    internal readonly record struct BotEvent(BotEventKind Kind, int A = 0, int B = 0, string? Text = null, byte[]? Data = null);

    /// <summary>
    ///     The protocol side of a bot: an in-process fake game client. It sends the same messages a real client
    ///     would send, straight into <see cref="Client.HandleMessageAsync"/>, so every server side validation still runs.
    /// </summary>
    internal sealed class BotClient
    {
        private readonly BotEnvironment _env;
        private readonly ILogger _logger;
        private readonly BotConnection _connection = new();
        private readonly System.Threading.SemaphoreSlim _sendLock = new(1, 1);
        private ClientBase? _client;
        private bool _disconnectReported;
        private ushort _systemSequence;

        public BotClient(BotEnvironment env, string name)
        {
            _env = env;
            Name = name;
            _logger = env.LoggerFactory.CreateLogger($"Bot[{name}]");
        }

        public string Name { get; }

        public BotConnection Connection => _connection;

        public ClientBase? Client => _client;

        public int ClientId => _client?.Id ?? 0;

        public bool IsConnected => _connection.IsConnected;

        public GameCode? Code { get; private set; }

        public int HostId { get; private set; }

        public Game? Game => _client?.Player?.Game;

        public InnerPlayerControl? Me => _client?.Player?.Character;

        public InnerPlayerInfo? MyInfo => Me?.PlayerInfo;

        public bool AmHost => Game != null && Game.HostId == ClientId;

        public bool SceneSent { get; private set; }

        /// <summary>
        ///     Gets or sets a hook that sees every event, in addition to the list returned by <see cref="DrainInbox"/>.
        /// </summary>
        public Action<BotEvent>? OnEvent { get; set; }

        /// <summary>
        ///     Gets or sets a value indicating whether raw inbound packets are dumped to the logger.
        /// </summary>
        public bool DumpInbound { get; set; }

        public async ValueTask<bool> ConnectAsync(GameVersion version)
        {
            await _env.ClientManager.RegisterConnectionAsync(
                _connection,
                Name,
                version,
                Language.English,
                QuickChatModes.FreeChatOrQuickChat,
                new PlatformSpecificData(Platforms.StandaloneSteamPC, "LLM Bot"));

            _client = _connection.Client as ClientBase;
            return _client != null && _connection.IsConnected;
        }

        public async ValueTask JoinAsync(GameCode code)
        {
            Code = code;
            SceneSent = false;

            await SendRootAsync(writer =>
            {
                writer.StartMessage(MessageFlags.JoinGame);
                writer.Write(code.Value);
                writer.Write(false);
                writer.EndMessage();
            });
        }

        public async ValueTask LeaveAsync(string reason = "The remote sent a disconnect request")
        {
            if (_client != null)
            {
                await _client.HandleDisconnectAsync(reason);
            }

            _connection.Close();
        }

        /// <summary>
        ///     Reads everything the server sent to this bot since the last call.
        /// </summary>
        public List<BotEvent> DrainInbox()
        {
            var events = new List<BotEvent>();

            while (_connection.Inbox.TryRead(out var bytes))
            {
                ParseInbound(bytes, events);
            }

            if (!_connection.IsConnected && _connection.DisconnectReason != null && !_disconnectReported)
            {
                _disconnectReported = true;
                events.Add(new BotEvent(BotEventKind.Disconnected, Text: _connection.DisconnectReason));
            }

            if (OnEvent != null)
            {
                foreach (var evt in events)
                {
                    OnEvent(evt);
                }
            }

            return events;
        }

        public async ValueTask SendSceneChangeAsync()
        {
            SceneSent = true;

            // Impostor hands out player ids while handling this message; two of them at the same instant can collide.
            await _env.JoinGate.WaitAsync();
            try
            {
                await SendGameDataAsync(
                    w =>
                    {
                        w.StartMessage(GameDataTag.SceneChangeFlag);
                        w.WritePacked(ClientId);
                        w.Write("OnlineGame");
                        w.EndMessage();
                    });
            }
            finally
            {
                _env.JoinGate.Release();
            }
        }

        public ValueTask SendReadyAsync()
        {
            return SendGameDataAsync(
                w =>
                {
                    w.StartMessage(GameDataTag.ReadyFlag);
                    w.WritePacked(ClientId);
                    w.EndMessage();
                });
        }

        public ValueTask SendRpcAsync(uint netId, RpcCalls call, Action<IMessageWriter>? payload = null, bool toHost = false)
        {
            return SendGameDataAsync(
                w =>
                {
                    w.StartMessage(GameDataTag.RpcFlag);
                    w.WritePacked(netId);
                    w.Write((byte)call);
                    payload?.Invoke(w);
                    w.EndMessage();
                },
                toHost ? HostId : null);
        }

        public async ValueTask SetupIdentityAsync(ColorType color, uint level)
        {
            var me = Me;
            if (me == null)
            {
                return;
            }

            await SendRpcAsync(me.NetId, RpcCalls.CheckName, w => w.Write(Name), toHost: true);
            await SendRpcAsync(me.NetId, RpcCalls.CheckColor, w => w.Write((byte)color), toHost: true);
            await SendRpcAsync(me.NetId, RpcCalls.SetLevel, w => w.WritePacked(level));
            await SendRpcAsync(me.NetId, RpcCalls.SetHatStr, w => { w.Write("hat_NoHat"); w.Write((byte)5); });
            await SendRpcAsync(me.NetId, RpcCalls.SetSkinStr, w => { w.Write("skin_None"); w.Write((byte)5); });
            await SendRpcAsync(me.NetId, RpcCalls.SetVisorStr, w => { w.Write("visor_EmptyVisor"); w.Write((byte)5); });
            await SendRpcAsync(me.NetId, RpcCalls.SetPetStr, w => { w.Write("pet_EmptyPet"); w.Write((byte)5); });
            await SendRpcAsync(me.NetId, RpcCalls.SetNamePlateStr, w => { w.Write("nameplate_NoPlate"); w.Write((byte)5); });
        }

        /// <summary>
        ///     Sends a position update (or a batch of them) for our own character.
        /// </summary>
        public ValueTask SendPositionAsync(Vector2 position)
        {
            var me = Me;
            if (me == null)
            {
                return default;
            }

            var seq = (ushort)(me.NetworkTransform.LastSequenceId + 1);
            return SendGameDataAsync(
                w =>
                {
                    w.StartMessage(GameDataTag.DataFlag);
                    w.WritePacked(me.NetworkTransform.NetId);
                    w.Write(seq);
                    w.WritePacked(1);
                    w.Write(position);
                    w.EndMessage();
                });
        }

        public ValueTask SnapToAsync(Vector2 position)
        {
            var me = Me;
            if (me == null)
            {
                return default;
            }

            var minSid = (ushort)(me.NetworkTransform.LastSequenceId + 5);
            return SendRpcAsync(
                me.NetworkTransform.NetId,
                RpcCalls.SnapTo,
                w =>
                {
                    w.Write(position);
                    w.Write(minSid);
                });
        }

        public ValueTask SendChatAsync(string text)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.NetId, RpcCalls.SendChat, w => w.Write(text));
        }

        public ValueTask CompleteTaskAsync(uint taskIndex)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.NetId, RpcCalls.CompleteTask, w => w.WritePacked(taskIndex));
        }

        public ValueTask CheckMurderAsync(InnerPlayerControl target)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.NetId, RpcCalls.CheckMurder, w => w.WritePacked(target.NetId));
        }

        public ValueTask ReportBodyAsync(byte deadPlayerId)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.NetId, RpcCalls.ReportDeadBody, w => w.Write(deadPlayerId));
        }

        /// <summary>
        ///     Repairs (or presses a console of) a sabotaged system. The host handles the request.
        /// </summary>
        /// <param name="system">The system being repaired.</param>
        /// <param name="amount">System specific: for reactor and O2 the low bits are the console and 0x40 means "used".</param>
        /// <returns>A task that finishes when the message was sent.</returns>
        public ValueTask SendUpdateSystemAsync(SystemTypes system, byte amount)
        {
            var me = Me;
            var ship = Game?.GameNet.ShipStatus;
            if (me == null || ship == null)
            {
                return default;
            }

            var seq = ++_systemSequence;
            return SendRpcAsync(ship.NetId, RpcCalls.UpdateSystem, w => Rpc35UpdateSystem.Serialize(w, system, me, seq, amount, 0), toHost: true);
        }

        public ValueTask EnterVentAsync(int ventId)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.Physics.NetId, RpcCalls.EnterVent, w => w.WritePacked(ventId));
        }

        public ValueTask ExitVentAsync(int ventId)
        {
            var me = Me;
            return me == null ? default : SendRpcAsync(me.Physics.NetId, RpcCalls.ExitVent, w => w.WritePacked(ventId));
        }

        /// <summary>
        ///     Casts a vote in the running meeting. <paramref name="suspect"/> is a player id, or 253 to skip.
        /// </summary>
        public async ValueTask CastVoteAsync(byte suspect)
        {
            var me = Me;
            var meeting = Game?.ActiveMeeting;
            if (me == null || meeting == null)
            {
                return;
            }

            await SendRpcAsync(
                meeting.NetId,
                RpcCalls.CastVote,
                w =>
                {
                    w.Write(me.PlayerId);
                    w.Write(suspect);
                },
                toHost: !AmHost);

            if (AmHost)
            {
                // A host records its own vote by updating the meeting object, everybody else sends the RPC above.
                await SendGameDataAsync(w =>
                {
                    w.StartMessage(GameDataTag.DataFlag);
                    w.WritePacked(meeting.NetId);
                    w.WritePacked(1u);
                    w.StartMessage(me.PlayerId);
                    w.Write(suspect);
                    w.Write(false);
                    w.EndMessage();
                    w.WritePacked(0);
                    w.EndMessage();
                });
            }
        }

        /// <summary>
        ///     Despawns our own character objects, as a real client does when it leaves the game over screen. Without this the
        ///     server keeps the old character, and after rejoining the bot would mistake it for its new one.
        /// </summary>
        /// <returns>The net id of the character that was removed, or null when there was none.</returns>
        public async ValueTask<uint?> DespawnMineAsync()
        {
            var me = Me;
            if (me == null)
            {
                return null;
            }

            var ids = new[] { me.NetId, me.Physics.NetId, me.NetworkTransform.NetId };
            await SendGameDataAsync(w =>
            {
                foreach (var id in ids)
                {
                    w.StartMessage(GameDataTag.DespawnFlag);
                    w.WritePacked(id);
                    w.EndMessage();
                }
            });

            return me.NetId;
        }

        public ValueTask SendGameDataAsync(Action<IMessageWriter> inner, int? toClient = null)
        {
            var code = Code;
            if (code == null)
            {
                return default;
            }

            return SendRootAsync(writer =>
            {
                if (toClient == null)
                {
                    writer.StartMessage(MessageFlags.GameData);
                    writer.Write(code.Value.Value);
                }
                else
                {
                    writer.StartMessage(MessageFlags.GameDataTo);
                    writer.Write(code.Value.Value);
                    writer.WritePacked(toClient.Value);
                }

                inner(writer);
                writer.EndMessage();
            });
        }

        public async ValueTask SendRootAsync(Action<IMessageWriter> build)
        {
            if (_client == null || !_connection.IsConnected)
            {
                return;
            }

            await _sendLock.WaitAsync();
            try
            {
                using var writer = MessageWriter.Get(MessageType.Reliable);
                build(writer);
                var bytes = writer.ToByteArray(false);

                using var reader = _env.ReaderPool.Get();
                reader.Update(bytes);

                while (reader.Position < reader.Length)
                {
                    using var message = reader.ReadMessage();
                    await _client.HandleMessageAsync(message, MessageType.Reliable);
                }
            }
            finally
            {
                _sendLock.Release();
            }
        }

        private void ParseInbound(byte[] bytes, List<BotEvent> events)
        {
            using var reader = _env.ReaderPool.Get();
            reader.Update(bytes);

            while (reader.Position < reader.Length)
            {
                using var message = reader.ReadMessage();
                try
                {
                    if (DumpInbound)
                    {
                        _logger.LogInformation("<< tag {Tag} len {Len}: {Hex}", message.Tag, message.Length, Convert.ToHexString(message.Buffer, message.Offset, Math.Min(message.Length, 64)));
                    }

                    switch (message.Tag)
                    {
                        case MessageFlags.HostGame:
                            events.Add(new BotEvent(BotEventKind.HostedGame, message.ReadInt32()));
                            break;

                        case MessageFlags.GameData:
                        case MessageFlags.GameDataTo:
                            ParseGameData(message, events);
                            break;

                        case MessageFlags.JoinedGame:
                        {
                            var code = message.ReadInt32();
                            var clientId = message.ReadInt32();
                            HostId = message.ReadInt32();
                            Code = GameCode.From(code);
                            events.Add(new BotEvent(BotEventKind.Joined, clientId, HostId));
                            break;
                        }

                        case MessageFlags.JoinGame:
                        {
                            // Another player joined; the host may have changed.
                            message.ReadInt32();
                            message.ReadInt32();
                            HostId = message.ReadInt32();
                            break;
                        }

                        case MessageFlags.WaitForHost:
                            events.Add(new BotEvent(BotEventKind.WaitForHost));
                            break;

                        case MessageFlags.StartGame:
                            events.Add(new BotEvent(BotEventKind.GameStarted));
                            break;

                        case MessageFlags.EndGame:
                        {
                            message.ReadInt32();
                            events.Add(new BotEvent(BotEventKind.GameEnded, message.ReadByte()));
                            break;
                        }

                        case MessageFlags.RemovePlayer:
                        {
                            message.ReadInt32();
                            var playerId = message.ReadInt32();
                            HostId = message.ReadInt32();
                            var reason = message.ReadByte();
                            events.Add(new BotEvent(BotEventKind.Removed, playerId, reason));
                            break;
                        }

                        case MessageFlags.KickPlayer:
                        {
                            message.ReadInt32();
                            var playerId = message.ReadPackedInt32();
                            events.Add(new BotEvent(BotEventKind.Kicked, playerId));
                            break;
                        }
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogWarning(ex, "Failed to parse inbound message {Tag}", message.Tag);
                }
            }
        }

        private void ParseGameData(IMessageReader message, List<BotEvent> events)
        {
            message.ReadInt32(); // game code
            if (message.Tag == MessageFlags.GameDataTo)
            {
                message.ReadPackedInt32(); // recipient, that is us
            }

            while (message.Position < message.Length)
            {
                using var sub = message.ReadMessage();
                switch (sub.Tag)
                {
                    case GameDataTag.SceneChangeFlag:
                    {
                        var clientId = sub.ReadPackedInt32();
                        events.Add(new BotEvent(BotEventKind.SceneChanged, clientId, Text: sub.ReadString()));
                        break;
                    }

                    case GameDataTag.ReadyFlag:
                        events.Add(new BotEvent(BotEventKind.ClientReady, sub.ReadPackedInt32()));
                        break;

                    case GameDataTag.RpcFlag:
                    {
                        var netId = sub.ReadPackedUInt32();
                        var call = sub.ReadByte();
                        var rest = sub.Length - sub.Position;
                        var data = new byte[rest];
                        Array.Copy(sub.Buffer, sub.Offset + sub.Position, data, 0, rest);
                        events.Add(new BotEvent(BotEventKind.Rpc, (int)netId, call, Data: data));
                        break;
                    }

                    case GameDataTag.SpawnFlag:
                        events.Add(new BotEvent(BotEventKind.Spawned, (int)sub.ReadPackedUInt32()));
                        break;

                    case GameDataTag.DespawnFlag:
                        events.Add(new BotEvent(BotEventKind.Despawned, (int)sub.ReadPackedUInt32()));
                        break;
                }
            }
        }
    }
}

using System;
using System.Linq;
using System.Net;
using System.Threading;
using System.Threading.Channels;
using System.Threading.Tasks;
using Impostor.Api.Net;
using Impostor.Hazel.Abstractions;

namespace Impostor.Server.LlmBots
{
    /// <summary>
    ///     An in-process connection. Everything the server "sends over the network" to a bot ends up in <see cref="Inbox"/>.
    /// </summary>
    internal sealed class BotConnection : IHazelConnection
    {
        private static int _addressCounter;

        private readonly Channel<byte[]> _inbox = Channel.CreateUnbounded<byte[]>(new UnboundedChannelOptions
        {
            SingleReader = true,
        });

        public BotConnection()
        {
            // Every bot gets its own private address so an anti cheat ban of a bot never hits a human on 127.0.0.1.
            var n = Interlocked.Increment(ref _addressCounter);
            EndPoint = new IPEndPoint(new IPAddress(new byte[] { 10, 254, (byte)((n >> 8) & 0xFF), (byte)(n & 0xFF) }), 22023);
            IsConnected = true;
        }

        public ChannelReader<byte[]> Inbox => _inbox.Reader;

        public IPEndPoint EndPoint { get; }

        public bool IsConnected { get; private set; }

        public IClient? Client { get; set; }

        public float AveragePing => 0;

        /// <summary>
        ///     Gets or sets a value indicating whether the server drops (instead of punishing) messages the anti cheat rejects.
        ///     Bots are exempt; the scripted test host is not, so tests stay strict about its behaviour.
        /// </summary>
        public bool ExemptFromAntiCheat { get; set; } = true;

        public string? DisconnectReason { get; private set; }

        public ValueTask SendAsync(IMessageWriter writer)
        {
            // The writer is pooled by the caller, copy the payload right now.
            if (IsConnected)
            {
                _inbox.Writer.TryWrite(writer.ToByteArray(false));
            }

            return default;
        }

        public ValueTask DisconnectAsync(string? reason, IMessageWriter? writer = null)
        {
            if (IsConnected)
            {
                IsConnected = false;
                DisconnectReason = reason ?? "disconnected";
                if (writer != null)
                {
                    // The server explains a disconnect in a text inside the message, keep it for the logs.
                    var bytes = writer.ToByteArray(false);
                    var text = new string(bytes.Select(b => b >= 32 && b < 127 ? (char)b : ' ').ToArray());
                    DisconnectReason += ": " + string.Join(' ', text.Split(' ', StringSplitOptions.RemoveEmptyEntries));
                }

                _inbox.Writer.TryComplete();
            }

            return default;
        }

        public void Close()
        {
            IsConnected = false;
            _inbox.Writer.TryComplete();
        }
    }
}

using Impostor.Api.Events.Managers;
using Impostor.Api.Utils;
using Impostor.Hazel;
using Impostor.Server.Net.Manager;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.ObjectPool;

namespace Impostor.Server.LlmBots
{
    /// <summary>
    ///     Shared services every bot needs to talk to the server.
    /// </summary>
    internal sealed class BotEnvironment
    {
        public BotEnvironment(
            ClientManager clientManager,
            GameManager gameManager,
            IEventManager eventManager,
            IDateTimeProvider clock,
            ObjectPool<MessageReader> readerPool,
            ILoggerFactory loggerFactory,
            LlmBotsConfig config,
            GameEventHub hub)
        {
            ClientManager = clientManager;
            GameManager = gameManager;
            EventManager = eventManager;
            Clock = clock;
            ReaderPool = readerPool;
            LoggerFactory = loggerFactory;
            Config = config;
            Hub = hub;
        }

        public ClientManager ClientManager { get; }

        public GameManager GameManager { get; }

        public IEventManager EventManager { get; }

        public IDateTimeProvider Clock { get; }

        public ObjectPool<MessageReader> ReaderPool { get; }

        public ILoggerFactory LoggerFactory { get; }

        public LlmBotsConfig Config { get; }

        public GameEventHub Hub { get; }

        /// <summary>
        ///     Gets the gate that serializes the scene change handshake of bots. Impostor assigns player ids while
        ///     handling that message and is not safe against several clients doing so in the same instant.
        /// </summary>
        public System.Threading.SemaphoreSlim JoinGate { get; } = new(1, 1);
    }
}
